        srli    r10, r5, 8
        andi    r10, r10, 0xFF
        srli    r11, r6, 16
        andi    r11, r11, 0xFF
        srli    r12, r7, 24
        lbux    r9, [r19 + r9]
        lbux    r10, [r19 + r10]
        lbux    r11, [r19 + r11]
        lbux    r12, [r19 + r12]
        slli    r10, r10, 8
        slli    r11, r11, 16
        slli    r12, r12, 24
        xor     r4, r4, r9
        xor     r4, r4, r10
        xor     r4, r4, r11
        xor     r4, r4, r12
        ret

; aes_ctr: encrypt r2 blocks at r1 in place in CTR mode, counter block
; ctr0, key schedule at rkeys. Returns the checksum in r1.
;
; Counter-mode caching: the counter block changes only in its last byte
; except once every 256 blocks. Round 1 output column j takes one byte from
; each input column, and only column 0 takes byte 15, so within a run of
; 256 blocks round 1 changes only in column 0:
;   t0 = P0 ^ Te3[byte 15 ^ round key 0 byte 15]
; Round 2 output column j takes exactly one byte of t0, so
;   u0 = Q0 ^ Te0[row 0 of t0]   u1 = Q1 ^ Te3[row 3 of t0]
;   u2 = Q2 ^ Te2[row 2 of t0]   u3 = Q3 ^ Te1[row 1 of t0]
; P0 and Q0-Q3 are worked out at the start of each run. A block then costs
; 21 instructions for rounds 0-2 instead of 144.
;   r20 P0   r21-r24 Q0-Q3   r25 round key 0 byte 15   r26 counter low word
;   r27 buffer pointer   r28 checksum   r29 blocks left in this run
;   ctr_blk: the counter block's words 0-2 (as loaded), ctr_left: blocks
;   left after this run
aes_ctr:
        addi    sp, sp, -60
        sw      lr, [sp + 56]
        sw      r16, [sp + 52]
        sw      r17, [sp + 48]
        sw      r18, [sp + 44]
        sw      r19, [sp + 40]
        sw      r20, [sp + 36]
        sw      r21, [sp + 32]
        sw      r22, [sp + 28]
        sw      r23, [sp + 24]
        sw      r24, [sp + 20]
        sw      r25, [sp + 16]
        sw      r26, [sp + 12]
        sw      r27, [sp + 8]
        sw      r28, [sp + 4]
        sw      r29, [sp]
        mov     r27, r1
        sw      r2, [ctr_left]
        la      r13, te0
        la      r14, te1
        la      r15, te2
        la      r16, te3
        la      r19, sbox
        lw      r1, [ctr0]              ; working copy of counter words 0-2
        lw      r2, [ctr0 + 4]
        lw      r3, [ctr0 + 8]
        sw      r1, [ctr_blk]
        sw      r2, [ctr_blk + 4]
        sw      r3, [ctr_blk + 8]
        lw      r1, [ctr0 + 12]         ; counter bytes 12-15, little-endian ...
        call    bswap
        mov     r26, r1                 ; ... as a number
        lw      r25, [rkeys + 12]
        srli    r25, r25, 24            ; round key 0, byte 15
        li      r28, 0

        ; start a run: up to 256 blocks in which only byte 15 changes
.run:   andi    r29, r26, 0xFF
        sub     r29, r0, r29
        addi    r29, r29, 256           ; blocks until byte 15 wraps
        lw      r1, [ctr_left]
        bgeu    r1, r29, .full
        mov     r29, r1                 ; (fewer left than that)
.full:  sub     r1, r1, r29
        sw      r1, [ctr_left]
        mov     r1, r26
        call    bswap
        mov     r4, r1
        lw      r1, [ctr_blk]
        lw      r2, [ctr_blk + 4]
        lw      r3, [ctr_blk + 8]
        call    aes_r12                 ; rounds 1-2 of the run's first block
        andi    r9, r26, 0xFF           ; take byte 15's terms back out
        xor     r9, r9, r25
        slli    r9, r9, 2
        lwx     r9, [r16 + r9]
        xor     r20, r5, r9             ; P0
        slli    r9, r5, 2
        andi    r9, r9, 0x3FC
        srli    r10, r5, 22
        andi    r10, r10, 0x3FC
        srli    r11, r5, 14
        andi    r11, r11, 0x3FC
        srli    r12, r5, 6
        andi    r12, r12, 0x3FC
        lwx     r9, [r13 + r9]
        lwx     r10, [r16 + r10]
        lwx     r11, [r15 + r11]
        lwx     r12, [r14 + r12]
        xor     r21, r1, r9             ; Q0
        xor     r22, r2, r10            ; Q1
        xor     r23, r3, r11            ; Q2
        xor     r24, r4, r12            ; Q3

        ; one block
.blk:   andi    r9, r26, 0xFF           ; rounds 0-1: column 0 only
        xor     r9, r9, r25
        slli    r9, r9, 2
        lwx     r9, [r16 + r9]
        xor     r5, r20, r9             ; t0
        slli    r9, r5, 2               ; round 2: one term per column
        andi    r9, r9, 0x3FC
        srli    r10, r5, 22
        andi    r10, r10, 0x3FC
        srli    r11, r5, 14
        andi    r11, r11, 0x3FC
        srli    r12, r5, 6
        andi    r12, r12, 0x3FC
        lwx     r9, [r13 + r9]
        lwx     r10, [r16 + r10]
        lwx     r11, [r15 + r11]
        lwx     r12, [r14 + r12]
        xor     r1, r21, r9
        xor     r2, r22, r10
        xor     r3, r23, r11
        xor     r4, r24, r12
        la      r17, rkeys + 32
        call    aes_rounds3
        lw      r5, [r27]               ; xor the keystream into the data
        lw      r6, [r27 + 4]
        lw      r7, [r27 + 8]
        lw      r8, [r27 + 12]
        xor     r1, r1, r5
        xor     r2, r2, r6
        xor     r3, r3, r7
        xor     r4, r4, r8
        sw      r1, [r27]
        sw      r2, [r27 + 4]
        sw      r3, [r27 + 8]
        sw      r4, [r27 + 12]
        rori    r28, r28, 27            ; checksum: rotl 5, add
        add     r28, r28, r1
        rori    r28, r28, 27
        add     r28, r28, r2
        rori    r28, r28, 27
        add     r28, r28, r3
        rori    r28, r28, 27
        add     r28, r28, r4
        addi    r27, r27, 16
        addi    r26, r26, 1             ; next counter block
        dbnz    r29, .blk

        lw      r1, [ctr_left]
        beqz    r1, .done
        bnez    r26, .run
        ; the low word wrapped: carry into words 2, 1, 0 (big-endian)
        la      r9, ctr_blk + 8
.carry: lw      r1, [r9]
        call    bswap
        addi    r1, r1, 1
        mov     r10, r1
        call    bswap
        sw      r1, [r9]
        addi    r9, r9, -4
        beqz    r10, .carry
        j       .run
.done:  mov     r1, r28
        lw      r29, [sp]
        lw      r28, [sp + 4]
        lw      r27, [sp + 8]
        lw      r26, [sp + 12]
        lw      r25, [sp + 16]
        lw      r24, [sp + 20]
        lw      r23, [sp + 24]
        lw      r22, [sp + 28]
        lw      r21, [sp + 32]
        lw      r20, [sp + 36]
        lw      r19, [sp + 40]
        lw      r18, [sp + 44]
        lw      r17, [sp + 48]
        lw      r16, [sp + 52]
        lw      lr, [sp + 56]
        addi    sp, sp, 60
        ret

; bswap: reverse the bytes of r1. Leaf; uses r1, r6-r8.
bswap:  li      r6, 0x00FF00FF
        rori    r7, r1, 8
        rori    r8, r1, 24
        andn    r7, r7, r6
        and     r8, r8, r6
        or      r1, r7, r8
        ret


; aes_setkey: expand the 16-byte key at r1 (word-aligned) into rkeys.
; Leaf; uses r1-r12. Words are little-endian, so RotWord is a rotate right
; by 8 and Rcon goes into the low byte.
aes_setkey:
        lw      r2, [r1]
        lw      r3, [r1 + 4]
        lw      r4, [r1 + 8]
        lw      r5, [r1 + 12]
        la      r6, rkeys
        la      r7, sbox
        li      r8, 1                   ; rcon
        li      r9, 10
        sw      r2, [r6]
        sw      r3, [r6 + 4]
        sw      r4, [r6 + 8]
        sw      r5, [r6 + 12]
.key:   rori    r10, r5, 8              ; RotWord
        andi    r11, r10, 0xFF          ; SubWord, a byte at a time
        lbux    r1, [r7 + r11]
        srli    r11, r10, 8
        andi    r11, r11, 0xFF
        lbux    r11, [r7 + r11]
        slli    r11, r11, 8
        xor     r1, r1, r11
        srli    r11, r10, 16
        andi    r11, r11, 0xFF
        lbux    r11, [r7 + r11]
        slli    r11, r11, 16
        xor     r1, r1, r11
        srli    r11, r10, 24
        lbux    r11, [r7 + r11]
        slli    r11, r11, 24
        xor     r1, r1, r11
        xor     r1, r1, r8              ; Rcon
        slli    r8, r8, 1               ; next Rcon = xtime(rcon)
        srli    r12, r8, 8
        neg     r12, r12
        andi    r12, r12, 0x11B
        xor     r8, r8, r12
        xor     r2, r2, r1
        xor     r3, r3, r2
        xor     r4, r4, r3
        xor     r5, r5, r4
        addi    r6, r6, 16
        sw      r2, [r6]
        sw      r3, [r6 + 4]
        sw      r4, [r6 + 8]
        sw      r5, [r6 + 12]
        dbnz    r9, .key
        ret

; aes_tables: build exp/log over GF(2^8) (generator 3), the S-box and
; Te0-Te3. Leaf; uses r1-r15.
aes_tables:
        la      r1, gexp
        la      r2, glog
        li      r3, 1                   ; p = 3^i
        li      r4, 0                   ; i
        li      r5, 255
.el:    add     r6, r1, r4
        sb      r3, [r6]                ; exp[i] = p
        add     r6, r2, r3
        sb      r4, [r6]                ; log[p] = i
        slli    r6, r3, 1               ; p *= 3: p ^ xtime(p)
        srli    r7, r3, 7
        neg     r7, r7
        andi    r7, r7, 0x11B
        xor     r6, r6, r7
        xor     r3, r3, r6
        addi    r4, r4, 1
        dbnz    r5, .el
        li      r3, 1
        sb      r3, [r1 + 255]          ; exp[255] = exp[0], for inv(1)
        la      r3, sbox
        la      r8, te0
        li      r4, 0                   ; x
        li      r5, 256
.sb:    lbux    r6, [r2 + r4]           ; log x
        sub     r6, r0, r6
        addi    r6, r6, 255
        lbux    r6, [r1 + r6]           ; x^-1 = exp[255 - log x] ...
        sltu    r7, r0, r4
        neg     r7, r7
        and     r6, r6, r7              ; ... and 0 for x = 0
        slli    r7, r6, 8               ; affine map: b ^ rotl(b, 1..4) ^ 0x63
        or      r7, r7, r6              ; b doubled up, so rotl8(b, k) = (bb >> (8-k)) & 0xFF
        srli    r9, r7, 7
        xor     r6, r6, r9
        srli    r9, r7, 6
        xor     r6, r6, r9
        srli    r9, r7, 5
        xor     r6, r6, r9
        srli    r9, r7, 4
        xor     r6, r6, r9
        andi    r6, r6, 0xFF
        xori    r6, r6, 0x63            ; s = S[x]
        add     r9, r3, r4
        sb      r6, [r9]
        slli    r9, r6, 1               ; 2s
        srli    r10, r6, 7
        neg     r10, r10
        andi    r10, r10, 0x11B
        xor     r9, r9, r10
        xor     r10, r9, r6             ; 3s
        slli    r11, r6, 8
        or      r9, r9, r11
        slli    r11, r6, 16
        or      r9, r9, r11
        slli    r10, r10, 24
        or      r9, r9, r10             ; Te0[x] = (2s, s, s, 3s)
        sw      r9, [r8]
        rori    r10, r9, 24
        sw      r10, [r8 + 1024]        ; Te1 = rotl(Te0, 8)
        rori    r10, r9, 16
        sw      r10, [r8 + 2048]        ; Te2 = rotl(Te0, 16)
        rori    r10, r9, 8
        sw      r10, [r8 + 3072]        ; Te3 = rotl(Te0, 24)
        addi    r8, r8, 4
        addi    r4, r4, 1
        dbnz    r5, .sb
        ret

; lcg_fill: store r2 words (even, 2 or more) of x = LCG_A x + LCG_C at r1,
; starting from the seed r3 (x1 first). Leaf; uses r1-r10.
; The multiplier is slow and can't overlap itself, so the work is split:
; it makes every other word, two steps ahead (x[n+2] = LCG_A2 x[n] + LCG_C2),
; while the ALU makes the word in between with shifts and adds
; (LCG_A = 25 * 139 * 479) in the multiply's shadow.
lcg_fill:
        li      r4, LCG_A2
        li      r5, LCG_C2
        li      r7, LCG_C
        li      r8, LCG_A
        multu   r3, r8
        mflo    r6
        add     r6, r6, r7              ; x1
        srli    r2, r2, 1               ; pairs
.loop:  multu   r6, r4                  ; x[n+2], meanwhile x[n+1] = A x[n] + C:
        slli    r8, r6, 4
        slli    r9, r6, 3
        add     r8, r8, r9
        add     r8, r8, r6              ; x * 25
        slli    r9, r8, 7
        slli    r10, r8, 3
        add     r9, r9, r10
        slli    r10, r8, 1
        add     r9, r9, r10
        add     r8, r9, r8              ; * 139
        slli    r9, r8, 9
        slli    r10, r8, 5
        sub     r9, r9, r10
        sub     r8, r9, r8              ; * 479
        add     r8, r8, r7              ; + C
        sw      r6, [r1]
        sw      r8, [r1 + 4]
        addi    r1, r1, 8
        mflo    r6
        add     r6, r6, r5
        dbnz    r2, .loop
        ret

        .data
        .align  4
key_c1: .byte   0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07
        .byte   0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f
pt_c1:  .byte   0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77
        .byte   0x88, 0x99, 0xaa, 0xbb, 0xcc, 0xdd, 0xee, 0xff
key_ctr:
        .byte   0x2b, 0x7e, 0x15, 0x16, 0x28, 0xae, 0xd2, 0xa6
        .byte   0xab, 0xf7, 0x15, 0x88, 0x09, 0xcf, 0x4f, 0x3c
ctr0:   .byte   0xf0, 0xf1, 0xf2, 0xf3, 0xf4, 0xf5, 0xf6, 0xf7
        .byte   0xf8, 0xf9, 0xfa, 0xfb, 0xfc, 0xfd, 0xfe, 0xff
rkeys:  .space  176
ctr_blk: .space 12
ctr_left: .space 4
te0:    .space  1024                    ; te0-te3 must be consecutive
te1:    .space  1024
te2:    .space  1024
te3:    .space  1024
sbox:   .space  256
gexp:   .space  256
glog:   .space  256
lab_c1: .asciz  "fips-197-c1"
lab_ctr:
        .asciz  "ctr-16k-checksum"
